INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (62, 1, '역색인이 무엇인지 알기', '검색 엔진의 핵심 자료구조로, 일반 인덱스가 "문서 → 단어" 방향인 것과 반대로 **"단어 → 그 단어가 든 문서 목록"** 방향으로 저장해서, 전체 문서를 순회하지 않고도 단어가 든 문서를 빠르게 찾게 해 줍니다. 무엇일까요?', '단어를 키로, 문서 ID 목록(posting list)을 값으로 가집니다.', NULL, NULL, '[]', 'choice', '["역색인 (Inverted Index)", "B-Tree 인덱스", "Translog", "Segment Merge"]', 0, '**역색인**은 term(단어) → 문서 ID 목록(posting list)을 저장합니다. "elasticsearch" 라는 단어가 든 문서를 찾으려고 100만 건을 순회하지 않고 키 하나로 바로 찾습니다. Elasticsearch 가 풀텍스트 검색에 빠른 이유입니다.', NULL, NULL, NULL, NULL),
  (62, 2, 'Shard 가 무엇인지 알기', 'Elasticsearch 에서 **샤드(Shard)** 에 대한 설명으로 알맞은 것은 무엇일까요?', '인덱스를 쪼개 여러 노드에 나누어 저장하기 위한 단위입니다.', NULL, NULL, '[]', 'choice', '["하나의 문서 안의 필드를 뜻한다", "인덱스를 **물리적으로 나눈 단위**이며 하나의 샤드는 독립적인 Lucene 인덱스이다. 색인과 검색이 샤드 단위로 실행된다", "클러스터의 상태 색깔을 뜻한다", "검색 결과의 점수를 뜻한다"]', 1, '인덱스는 하나 이상의 **샤드**로 나뉘어 여러 Data Node 에 분산 저장됩니다. 그래서 데이터와 트래픽을 여러 노드가 나눠 처리합니다. 샤드 하나는 독립적인 Lucene 인덱스입니다.', NULL, NULL, NULL, NULL),
  (62, 3, 'Primary 샤드와 Replica 샤드의 역할 알기', 'Replica 샤드의 역할로 알맞은 것은 무엇일까요?', '복제본은 장애 대비와 읽기 분산 두 가지 일을 합니다.', NULL, NULL, '[]', 'choice', '["색인 요청을 항상 먼저 받는다", "클러스터 메타데이터를 관리한다", "Primary 의 복제본으로, 장애 시 Primary 를 **대체**하고 읽기(검색) 요청을 **분산**해 처리량을 높인다", "오래된 문서를 삭제한다"]', 2, '색인 요청은 항상 **Primary** 로 먼저 가고 Replica 로 복제됩니다. Replica 는 Primary 가 있는 노드가 죽었을 때 승격되어 서비스를 이어 가고, 검색 요청도 나눠 받습니다. 그래서 Primary 와 그 Replica 는 **같은 노드에 두지 않습니다.**', NULL, NULL, NULL, NULL),
  (62, 4, '클러스터 상태 색깔 읽기', '`GET _cluster/health` 의 상태가 **yellow** 입니다. 무슨 뜻일까요?', 'green 은 전부 정상입니다. yellow 는 그보다 한 단계 아래, red 는 그보다 위험합니다.', NULL, NULL, '[]', 'choice', '["모든 **Primary 샤드는 할당**되어 데이터는 모두 접근 가능하지만, 일부 **Replica 샤드가 할당되지 않은** 상태이다", "모든 샤드가 정상 할당된 완전 정상 상태이다", "일부 Primary 샤드가 할당되지 않아 그 데이터에 접근할 수 없다", "클러스터가 아직 시작되지 않았다"]', 0, '**green**: 모든 Primary·Replica 정상. **yellow**: Primary 는 모두 정상이라 데이터는 다 있지만 일부 Replica 가 미할당(노드가 부족하거나 장애 직후 등)이라 중복성이 줄어든 상태. **red**: 일부 Primary 가 미할당이라 그 데이터는 읽고 쓸 수 없는 위험한 상태입니다. 노드 하나짜리 개발 환경에서 replica 가 1 이면 yellow 가 되는 것도 흔합니다.', NULL, NULL, NULL, NULL),
  (62, 5, '노드 역할 구분하기', '클라이언트 요청을 받아 **관련 샤드들에 나눠 보내고 결과를 모아 반환**하는 일만 하며, **데이터를 저장하지 않는** 노드 역할은 무엇일까요?', '모든 노드가 기본으로 이 역할을 겸하지만, 이것만 전담하게 둘 수도 있습니다.', NULL, NULL, '[]', 'choice', '["Master Node", "Coordinating Node", "Data Node", "Replica Node"]', 1, '**Master** 는 클러스터 상태(인덱스 생성·삭제, 샤드 할당, 노드 추가·제거)를 관리하고 데이터를 처리하지 않으며, **Data** 는 샤드를 저장하고 색인·검색을 처리하고, **Coordinating** 은 요청 라우팅과 결과 집계만 합니다. 프로덕션에서는 Master 를 전용으로 분리해 클러스터 전체가 영향받지 않게 합니다.', NULL, NULL, NULL, NULL),
  (62, 6, 'refresh 와 flush 의 차이 알기', 'Elasticsearch 의 **refresh** 와 **flush** 의 차이로 알맞은 것은 무엇일까요?', '하나는 "검색 가능하게", 다른 하나는 "디스크에 안전하게" 입니다.', NULL, NULL, '[]', 'choice', '["`refresh` 가 디스크에 영구 저장하고 `flush` 가 검색 가능하게 한다", "둘은 같은 작업의 다른 이름이다", "`refresh` 는 메모리 버퍼의 문서를 새 Segment 로 만들어 **검색 가능**하게 하고, `flush` 는 Segment 를 디스크에 **영구 저장(fsync)** 하고 그 시점까지의 Translog 를 정리한다", "`refresh` 는 문서를 삭제하고 `flush` 는 복제한다"]', 2, '색인한 문서는 먼저 메모리 버퍼(그리고 Translog)에 쌓입니다. **refresh** 로 새 Segment(OS 파일 캐시)가 되어야 검색에 잡힙니다. **flush** 는 그 Segment 를 디스크에 fsync 하고 checkpoint 를 기록한 뒤 이전 Translog 를 지웁니다.', NULL, NULL, NULL, NULL),
  (62, 7, '색인한 문서가 안전하게 저장되기까지 순서 놓기', '문서를 색인했을 때 일어나는 일을 **앞에서 뒤 순서**대로 놓으세요.', '검색 가능해지는 것과 디스크에 영구 저장되는 것은 서로 다른 단계입니다.', NULL, NULL, '[]', 'order', '["flush 로 Segment 를 디스크에 fsync 하고 checkpoint 를 기록한다", "refresh 로 버퍼가 새 Segment 가 되어 검색 가능해진다", "checkpoint 이전의 Translog 가 삭제된다", "문서가 메모리 버퍼에 쌓이고 Translog 에 기록된다"]', NULL, '**버퍼 + Translog 기록 → refresh(검색 가능) → flush(디스크 fsync, checkpoint) → 이전 Translog 삭제** 순서입니다. 검색 가능해지는 시점(refresh)과 디스크에 안전하게 저장되는 시점(flush)이 다르기 때문에, 그 사이 장애가 나면 Translog 를 재실행해 복구합니다.', '[3, 1, 0, 2]', NULL, NULL, NULL),
  (62, 8, 'Translog 의 역할 알기', 'Elasticsearch 의 **Translog** 는 왜 필요할까요?', '데이터베이스의 WAL(Write-Ahead Log)과 같은 역할입니다.', NULL, NULL, '[]', 'choice', '["검색 결과를 점수순으로 정렬하기 위해서이다", "오래된 Segment 를 합치기 위해서이다", "클러스터 상태를 색깔로 표시하기 위해서이다", "flush 전에 노드가 죽어도, 색인 요청을 먼저 기록해 둔 Translog 를 재시작 때 **재실행해 데이터를 복구**하기 위해서이다"]', 3, '새 문서는 바로 디스크에 쓰이지 않고 메모리 버퍼에 있다가 refresh → flush 를 거칩니다. flush 전에 노드가 죽으면 버퍼는 사라지는데, 색인 요청마다 먼저 **Translog**(Write-Ahead Log)에 기록해 두었기 때문에 재시작 후 재실행으로 복구할 수 있습니다.', NULL, NULL, NULL, NULL),
  (62, 9, 'Segment 의 불변성 알기', 'Elasticsearch 에서 문서를 **수정**하면 내부적으로 어떻게 처리될까요? (Segment 는 한번 생성되면 수정되지 않습니다)', '기존 Segment 를 고치지 못한다면 어떻게 "수정"할까요?', NULL, NULL, '[]', 'choice', '["기존 Segment 의 문서에 **삭제 표시**를 하고, **새 Segment 에 새 버전**을 쓴다. 쌓인 작은 Segment 들은 나중에 merge 로 합쳐진다", "기존 Segment 를 직접 덮어쓴다", "문서를 수정할 수 없고 오류가 난다", "인덱스 전체를 다시 만든다"]', 0, 'Segment 는 **불변(immutable)** 입니다. 수정은 "기존 것에 삭제 표시 + 새 Segment 에 새 버전 추가"이고, 삭제 표시된 문서는 **merge** 때 실제로 제거됩니다. 불변이라 동시성 제어가 단순하고 OS 파일 캐시를 효율적으로 쓸 수 있지만, Segment 가 많이 쌓이면 검색이 느려져 merge 가 필요합니다.', NULL, NULL, NULL, NULL),
  (62, 10, 'text 와 keyword 필드 구분하기', '`product_name`(상품명, 풀텍스트 검색용)과 `status`(`ACTIVE` 같은 정확한 값 비교용)의 매핑 타입으로 알맞은 것은 무엇일까요?', '하나는 분석기(Analyzer)로 토큰을 나누고, 다른 하나는 원문 그대로 저장합니다.', NULL, NULL, '[]', 'choice', '["둘 다 `keyword` 로 하는 것이 항상 맞다", "`product_name` 은 `text`(분석해서 토큰으로 나눔), `status` 는 `keyword`(분석 없이 원문 그대로)", "`product_name` 은 `keyword`, `status` 는 `text`", "둘 다 `date` 로 한다"]', 1, '`text` 는 Analyzer 를 거쳐 토큰으로 나뉘어 역색인에 저장되므로 부분 단어 검색에 쓰고, `keyword` 는 원문 그대로 저장되어 **정확히 일치하는 값 비교, 정렬, 집계**에 씁니다. 매핑은 관계형 DB 의 스키마에 해당하며 필드 타입을 잘못 잡으면 검색이 기대와 다르게 동작합니다.', NULL, NULL, NULL, NULL),
  (62, 11, 'query 컨텍스트와 filter 컨텍스트 구분하기', '검색에서 **날짜 범위**나 **카테고리 일치** 같은 조건은 `query` 절 대신 `filter` 절에 넣는 것이 유리하다고 합니다. 이유는 무엇일까요?', 'filter 는 "만족하는가" 만, query 는 "얼마나 관련있는가" 까지 계산합니다.', NULL, NULL, '[]', 'choice', '["`filter` 가 점수를 더 정확히 계산하기 때문이다", "`query` 절에는 날짜를 쓸 수 없기 때문이다", "`filter` 는 yes/no 만 판단하고 **점수 계산이 없으며 결과가 캐시**되기 때문이다", "`filter` 는 문서를 삭제하기 때문이다"]', 2, '**Query Context** 는 relevance score(BM25 등)를 계산하고, **Filter Context** 는 조건 충족 여부만 판단해 점수 계산을 생략하며 캐싱됩니다. 점수가 필요 없는 조건(날짜 범위, 상태, 카테고리)은 filter 에 넣어 성능을 챙깁니다.', NULL, NULL, NULL, NULL),
  (62, 12, '색인 직후 검색이 안 잡히는 이유 알기', '문서를 방금 색인했는데 바로 검색하면 결과에 **나오지 않을 수** 있습니다. 이유는 무엇일까요?', 'Elasticsearch 는 "거의 실시간(Near Real-Time)" 검색입니다.', NULL, NULL, '[]', 'choice', '["문서가 삭제되었기 때문이다", "샤드가 합쳐졌기 때문이다", "검색 서버가 꺼졌기 때문이다", "색인된 문서는 **refresh** 가 실행되어 새 Segment 가 만들어져야 검색 대상에 포함되기 때문이다"]', 3, 'Elasticsearch 는 실시간이 아니라 **Near Real-Time** 입니다. 색인 후 refresh 주기(기본값이 있고 설정으로 바꿀 수 있음) 뒤에야 검색에 보입니다. 반대로 refresh 를 너무 자주 하면 작은 Segment 가 많이 생겨 부담이 커집니다.', NULL, NULL, NULL, NULL);
